solution_plantuml:
@startuml
start
:Stoerung im Supportportal melden;

while (Pflichtangaben vollstaendig?) is (nein)
  :Fehlende Angaben anfordern;
  :Mitarbeiter ergaenzt Meldung;
endwhile (ja)

:Ticket erstellen;
:Kategorie und Prioritaet bestimmen;
:Supportgruppe zuordnen;
:Ticket uebernehmen;

if (Bekannte Loesung vorhanden?) then (ja)
  :Bekannte Loesung anwenden;
else (nein)
  :Ursache analysieren;

  while (Zusatzinformationen noetig?) is (ja)
    :Rueckfrage an Mitarbeiter senden;
    :Antwort abwarten;
    :Antwort pruefen;
  endwhile (nein)

  if (Im First-Level loesbar?) then (ja)
    :Loesung umsetzen;
  else (nein)
    :An Second-Level-Support eskalieren;
    :Problem im Second-Level analysieren;
    :Loesung erarbeiten und umsetzen;
  endif
endif

:Loesung dokumentieren;
:Mitarbeiter informieren;

if (Stoerung behoben?) then (ja)
  :Ticket schliessen;
else (nein)
  :Ticket erneut oeffnen;
  :Nachbearbeitung starten;
  :Loesung korrigieren;
  :Ticket schliessen;
endif

stop
@enduml
